// Generated by scripts.prepare_review_assets from the review template.

const study=JSON.parse(document.getElementById('study-data').textContent),el=id=>document.getElementById(id);let plan=[],participant='',profile={},index=0,start=0,startedAt='',hidden=[],results=[];
function hash(s){let x=2166136261;for(const c of s){x^=c.charCodeAt(0);x=Math.imul(x,16777619);}return x>>>0;}
function task(){if(index>=plan.length){el('task').hidden=true;el('progress').textContent='All assigned tasks complete. Confirm and export.';return;}const t=plan[index];el('title').textContent='Task '+(index+1)+' of '+plan.length;el('instruction').textContent=t.instruction;el('condition').textContent=t.condition==='manual'?'Manual: source text only':'Assisted: source plus recorded model draft';el('source').textContent=t.source.text;el('answer').value='';el('outcome').value='';el('assistance').replaceChildren();if(t.condition==='assisted'){const title=document.createElement('h3');title.textContent='Recorded Meta draft · verify every interpretation';el('assistance').append(title);for(const o of t.assistance.observations){const p=document.createElement('p');p.textContent=o.field+' / '+o.polarity+': '+o.value+' — '+o.evidence.quote;el('assistance').append(p);}if(!t.assistance.observations.length){const p=document.createElement('p');p.textContent='Model fallback: '+(t.assistance.fallback_reason||'No accepted observations');el('assistance').append(p);}}el('task').hidden=false;start=performance.now();startedAt=new Date().toISOString();hidden=[];}
el('begin').onclick=()=>{participant=el('participant').value.trim();profile={role:el('role').value.trim(),experience:el('experience').value.trim()};if(!participant||!profile.role||!profile.experience){el('notice').textContent='Enter your participant identifier, relevant role and experience first.';return;}const h=hash(participant);plan=study.tasks.map((t,i)=>({...t,condition:(i+(h%2))%2?'assisted':'manual'}));if((h>>>1)%2)plan.reverse();el('begin').disabled=true;el('participant').disabled=true;el('role').disabled=true;el('experience').disabled=true;task();};
document.addEventListener('visibilitychange',()=>{if(start)hidden.push({state:document.visibilityState,elapsed_ms:Math.round(performance.now()-start)});});
setInterval(()=>{if(start)el('timer').textContent=((performance.now()-start)/1000).toFixed(0)+' seconds elapsed';},1000);
el('finish').onclick=()=>{if(!el('answer').value.trim()||!el('outcome').value){el('notice').textContent='Write your evidence packet or explain why you could not complete it.';return;}const t=plan[index];results.push({task_id:t.task_id,condition:t.condition,answer:el('answer').value,task_outcome:el('outcome').value,started_at:startedAt,finished_at:new Date().toISOString(),elapsed_ms:Math.round(performance.now()-start),visibility_events:hidden});start=0;index++;el('progress').textContent=results.length+' completed';el('notice').textContent='Task recorded. Export regularly.';task();};
el('export').onclick=()=>{if(!participant||!results.length||!el('attest').checked){el('notice').textContent='Complete a task and confirm personal participation first.';return;}const out={session_schema_version:2,reviewer_profile:profile,study_hash:study.study_hash,participant,annotation_source:'human',attestation:true,timing_source:'browser_monotonic_elapsed_including_hidden_tabs',assignment:plan.map(t=>({task_id:t.task_id,condition:t.condition})),results};const u=URL.createObjectURL(new Blob([JSON.stringify(out,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='tracex-reviewer-session.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};

